class Solution:
    def maximumAlternatingSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        ans = -10 ** 18
        for i in range(n):
            s = 0
            for j in range(i, n):
                s += nums[j] if (j - i) % 2 == 0 else -nums[j]
                ans = max(ans, s)
        return ans

