class Solution:
    def maximumAlternatingSubarraySum(self, nums: List[int]) -> int:
        def kadane(arr):
            best = cur = arr[0]
            for x in arr[1:]:
                cur = max(x, cur + x)
                best = max(best, cur)
            return best

        f1 = [x if i % 2 == 0 else -x for i, x in enumerate(nums)]
        f2 = [-x if i % 2 == 0 else x for i, x in enumerate(nums)]
        return max(kadane(f1), kadane(f2))

