class Solution {
    public long maximumAlternatingSubarraySum(int[] nums) {
        return Math.max(kadane(nums, true), kadane(nums, false));
    }

    private long kadane(int[] nums, boolean evenPositive) {
        long best = Long.MIN_VALUE, cur = 0;
        for (int i = 0; i < nums.length; i++) {
            long v = (i % 2 == 0) == evenPositive ? nums[i] : -(long) nums[i];
            cur = Math.max(v, cur + v);
            best = Math.max(best, cur);
        }
        return best;
    }
};

