        const long long NEG = LLONG_MIN / 4;
        long long pos = NEG, neg = NEG, ans = NEG;
        for (int x : nums) {
            long long oldPos = pos;
            pos = max((long long)x, neg + x);
            neg = oldPos - x;
            ans = max(ans, max(pos, neg));
        }
        return ans;
    }
};

